#include "pseudonormal_test.h"
#include "barycentric_coordinates.h"
#include "doublearea.h"
#include "project_to_line_segment.h"
#include <cassert>
template <
  typename DerivedV,
  typename DerivedF,
  typename DerivedFN,
  typename DerivedVN,
  typename DerivedEN,
  typename DerivedEMAP,
  typename Derivedq,
  typename Derivedc,
  typename Scalar,
  typename Derivedn>
IGL_INLINE void igl::pseudonormal_test(
  const Eigen::MatrixBase<DerivedV> & V,
  const Eigen::MatrixBase<DerivedF> & F,
  const Eigen::MatrixBase<DerivedFN> & FN,
  const Eigen::MatrixBase<DerivedVN> & VN,
  const Eigen::MatrixBase<DerivedEN> & EN,
  const Eigen::MatrixBase<DerivedEMAP> & EMAP,
  const Eigen::MatrixBase<Derivedq> & q,
  const int f,
  Eigen::PlainObjectBase<Derivedc> & c,
  Scalar & s,
  Eigen::PlainObjectBase<Derivedn> & n)
{
  static_assert(DerivedV::ColsAtCompileTime == 3 || DerivedV::ColsAtCompileTime == Eigen::Dynamic,"V must either have 3 or Dynamic columns");
  static_assert(DerivedFN::ColsAtCompileTime == 3 || DerivedFN::ColsAtCompileTime == Eigen::Dynamic,"FN must either have 3 or Dynamic columns");
  static_assert(DerivedVN::ColsAtCompileTime == 3 || DerivedVN::ColsAtCompileTime == Eigen::Dynamic,"VN must either have 3 or Dynamic columns");
  static_assert(DerivedEN::ColsAtCompileTime == 3 || DerivedEN::ColsAtCompileTime == Eigen::Dynamic,"EN must either have 3 or Dynamic columns");
  static_assert(
      Derivedc::ColsAtCompileTime*Derivedc::RowsAtCompileTime == 3 || 
      Derivedc::ColsAtCompileTime*Derivedc::RowsAtCompileTime == Eigen::Dynamic,"c must be size 3 or Dynamic");
  static_assert(
      Derivedq::ColsAtCompileTime*Derivedq::RowsAtCompileTime == 3 || 
      Derivedq::ColsAtCompileTime*Derivedq::RowsAtCompileTime == Eigen::Dynamic,"q must be size 3 or Dynamic");
  static_assert(
      Derivedn::ColsAtCompileTime*Derivedn::RowsAtCompileTime == 3 || 
      Derivedn::ColsAtCompileTime*Derivedn::RowsAtCompileTime == Eigen::Dynamic,"q must be size 3 or Dynamic");
  const auto & qc = q-c;
  typedef Eigen::Matrix<Scalar,1,3> RowVector3S;
  RowVector3S b;
  // Using barycentric coorindates to determine whether close to a vertex/edge
  // seems prone to error when dealing with nearly degenerate triangles: Even
  // the barycenter (1/3,1/3,1/3) can be made arbitrarily close to an
  // edge/vertex
  //
  const RowVector3S A = V.row(F(f,0));
  const RowVector3S B = V.row(F(f,1));
  const RowVector3S C = V.row(F(f,2));

  const double area = [&A,&B,&C]()
  {
    Eigen::Matrix<double,1,1> area;
    doublearea(A,B,C,area);
    return area(0);
  }();
  // These were chosen arbitrarily. In a floating point scenario, I'm not sure
  // the best way to determine if c is on a vertex/edge or in the middle of the
  // face: specifically, I'm worrying about degenerate triangles where
  // barycentric coordinates are error-prone.
  const double MIN_DOUBLE_AREA = 1e-4;
  const double epsilon = 1e-12;
  if(area>MIN_DOUBLE_AREA)
  {
    barycentric_coordinates( c,A,B,C,b);
    // Determine which normal to use
    const int type = (b.array()<=epsilon).template cast<int>().sum();
    switch(type)
    {
      case 2:
        // Find vertex
        for(int x = 0;x<3;x++)
        {
          if(b(x)>epsilon)
          {
            n = VN.row(F(f,x));
            break;
          }
        }
        break;
      case 1:
        // Find edge
        for(int x = 0;x<3;x++)
        {
          if(b(x)<=epsilon)
          {
            n = EN.row(EMAP(F.rows()*x+f));
            break;
          }
        }
        break;
      default:
        assert(false && "all barycentric coords zero.");
      case 0:
        n = FN.row(f);
        break;
    }
  }else
  {
    // Check each vertex
    bool found = false;
    for(int v = 0;v<3 && !found;v++)
    {
      if( (c-V.row(F(f,v))).norm() < epsilon)
      {
        found = true;
        n = VN.row(F(f,v));
      }
    }
    // Check each edge
    for(int e = 0;e<3 && !found;e++)
    {
      const RowVector3S s = V.row(F(f,(e+1)%3));
      const RowVector3S d = V.row(F(f,(e+2)%3));
      Eigen::Matrix<double,1,1> sqr_d_j_x(1,1);
      Eigen::Matrix<double,1,1> t(1,1);
      project_to_line_segment(c,s,d,t,sqr_d_j_x);
      if(sqrt(sqr_d_j_x(0)) < epsilon)
      {
        n = EN.row(EMAP(F.rows()*e+f));
        found = true;
      }
    }
    // Finally just use face
    if(!found)
    {
      n = FN.row(f);
    }
  }
  s = (qc.dot(n) >= 0 ? 1. : -1.);
}

template <
  typename DerivedV,
  typename DerivedF,
  typename DerivedEN,
  typename DerivedVN,
  typename Derivedq,
  typename Derivedc,
  typename Scalar,
  typename Derivedn>
IGL_INLINE void igl::pseudonormal_test(
  const Eigen::MatrixBase<DerivedV> & V,
  const Eigen::MatrixBase<DerivedF> & E,
  const Eigen::MatrixBase<DerivedEN> & EN,
  const Eigen::MatrixBase<DerivedVN> & VN,
  const Eigen::MatrixBase<Derivedq> & q,
  const int e,
  Eigen::PlainObjectBase<Derivedc> & c,
  Scalar & s,
  Eigen::PlainObjectBase<Derivedn> & n)
{
  static_assert(DerivedV::ColsAtCompileTime == 2 || DerivedV::ColsAtCompileTime == Eigen::Dynamic,"V must either have 2 or Dynamic columns");
  static_assert(DerivedEN::ColsAtCompileTime == 2 || DerivedEN::ColsAtCompileTime == Eigen::Dynamic,"EN must either have 2 or Dynamic columns");
  static_assert(DerivedVN::ColsAtCompileTime == 2 || DerivedVN::ColsAtCompileTime == Eigen::Dynamic,"VN must either have 2 or Dynamic columns");
  static_assert(
      Derivedc::ColsAtCompileTime*Derivedc::RowsAtCompileTime == 2 || 
      Derivedc::ColsAtCompileTime*Derivedc::RowsAtCompileTime == Eigen::Dynamic,"c must be size 2 or Dynamic");
  static_assert(
      Derivedq::ColsAtCompileTime*Derivedq::RowsAtCompileTime == 2 || 
      Derivedq::ColsAtCompileTime*Derivedq::RowsAtCompileTime == Eigen::Dynamic,"q must be size 2 or Dynamic");
  static_assert(
      Derivedn::ColsAtCompileTime*Derivedn::RowsAtCompileTime == 2 || 
      Derivedn::ColsAtCompileTime*Derivedn::RowsAtCompileTime == Eigen::Dynamic,"q must be size 2 or Dynamic");
  const auto & qc = q-c;
  const double len = (V.row(E(e,1))-V.row(E(e,0))).norm();
  // barycentric coordinates
  // this .head() nonsense is for "ridiculus" templates instantiations that AABB
  // needs to compile
  Eigen::Matrix<Scalar,1,2>
    b((c-V.row(E(e,1))).norm()/len,(c-V.row(E(e,0))).norm()/len);
    //b((c-V.row(E(e,1)).head(c.size())).norm()/len,(c-V.row(E(e,0)).head(c.size())).norm()/len);
  // Determine which normal to use
  const double epsilon = 1e-12;
  const int type = (b.array()<=epsilon).template cast<int>().sum();
  switch(type)
  {
    case 1:
      // Find vertex
      for(int x = 0;x<2;x++)
      {
        if(b(x)>epsilon)
        {
          n = VN.row(E(e,x)).head(2);
          break;
        }
      }
      break;
    default:
      assert(false && "all barycentric coords zero.");
    case 0:
      n = EN.row(e).head(2);
      break;
  }
  s = (qc.dot(n) >= 0 ? 1. : -1.);
}

